import { useCallback, useMemo, useState } from 'react'

const useMapData = () => {
  const [mapPoints, setMapPoints] = useState([])
  const [selectedPoints, setSelectedPoints] = useState([])
  const [showPoliticalDots, setShowPoliticalDots] = useState(false)
  const [partyCounts, setPartyCounts] = useState([])
  const [selectedParties, setSelectedParties] = useState(new Set())
  const [isShapefileVisible, setIsShapefileVisible] = useState(true)
  const [visualizationType, setVisualizationType] = useState('points')

  // Memoize clear function to prevent unnecessary re-renders
  const clearMarkerData = useCallback(() => {
    setMapPoints([])
    setSelectedPoints([])
    setSelectedParties(new Set())
    setPartyCounts([])
    setShowPoliticalDots(false)
  }, [])

  // Memoize data objects to prevent recreation on every render
  const mapData = useMemo(() => ({
    mapPoints,
    selectedPoints,
    showPoliticalDots,
    partyCounts,
    selectedParties,
    isShapefileVisible,
    visualizationType,
  }), [mapPoints, selectedPoints, showPoliticalDots, partyCounts, selectedParties, isShapefileVisible, visualizationType])

  // Memoize setters object - setters are stable, so this only needs to be created once
  const setMapData = useMemo(() => ({
    setMapPoints,
    setSelectedPoints,
    setShowPoliticalDots,
    setPartyCounts,
    setSelectedParties,
    setIsShapefileVisible,
    setVisualizationType,
  }), [])

  return {
    mapData,
    setMapData,
    clearMarkerData,
  }
}

export default useMapData
