import { Alert, Button, Checkbox, Input, Modal, Radio, Select, Slider, Spin, Switch, message } from 'antd'
import React, { useEffect, useState } from 'react'
import { applyDataCleaning, applySorting, generateAndDownloadNewExcelFile, readExcelFile, reformatData } from '../utils/ExcelProcessingUtils.jsx'
import styles from './ExcelColumnSelector.module.css'

// Helper function to safely extract column key from column name
const extractColumnKey = (columnName) => {
  if (!columnName) return null
  const match = columnName.match(/\(([^)]+)\)/)
  return match ? match[1] : null
}

// eslint-disable-next-line @typescript-eslint/no-empty-function
function ExcelColumnSelector({ visible, onCancel, droppedFile, setMapPoints, setCurrentMapFile = () => {} }) {
  const [excelData, setExcelData] = useState(null)
  const [actionType, setActionType] = useState(null)
  const [error, setError] = useState(false)
  const [isLoading, setIsLoading] = useState(false)

  const [latitudeColumn, setLatitudeColumn] = useState(null)
  const [longitudeColumn, setLongitudeColumn] = useState(null)
  const [nameColumn, setNameColumn] = useState(null)

  const [selectedColumns, setSelectedColumns] = useState([])
  const [searchQuery, setSearchQuery] = useState('')
  const [sortColumn, setSortColumn] = useState(null)
  const [sortOrder, setSortOrder] = useState('ascend')
  const [cleanDataOptions, setCleanDataOptions] = useState({
    trimWhitespace: false,
    toUpperCase: false,
  })
  const [sliderValue, setSliderValue] = useState(0)
  const [maxRows, setMaxRows] = useState(0)
  const [selectAll, setSelectAll] = useState(true)

  useEffect(() => {
    if (!droppedFile) {
      return
    }

    setIsLoading(true)
    readExcelFile(droppedFile)
        .then((excelData) => {
          setExcelData(excelData)
          const firstColumnKey = excelData.columns.length > 0 ? extractColumnKey(excelData.columns[0]) : null
          if (firstColumnKey && excelData.data[firstColumnKey]) {
            setMaxRows(excelData.data[firstColumnKey].length)
            setSliderValue(excelData.data[firstColumnKey].length)
          }
        })
        .catch((error) => {
          console.error('Error reading file:', error)
          message.error('Failed to read Excel file')
        })
        .finally(() => {
          setIsLoading(false)
        })
  }, [droppedFile, visible])

  const handleCheckboxChange = (column) => {
    const updatedSelection = selectedColumns.includes(column) ?
      selectedColumns.filter((col) => col !== column) :
      [...selectedColumns, column]

    setSelectedColumns(updatedSelection)
  }

  const handleDataCleaningSwitch = (checked, option) => {
    setCleanDataOptions((prevOptions) => ({
      ...prevOptions,
      [option]: checked,
    }))
  }

  const toggleSelectAll = () => {
    setSelectAll(!selectAll) // Toggle the selectAll state
    setSelectedColumns(selectAll ? [] : [...excelData.columns]) // Select all or deselect all columns
  }

  const handleConfirm = () => {
    if (actionType === 'format') {
      let newData = applyDataCleaning(excelData.data, cleanDataOptions)

      if (sortColumn) {
        newData = applySorting(newData, sortColumn, sortOrder)
      }

      const newExcelData = reformatData({ ...excelData, data: newData }, selectedColumns)

      if (sliderValue < maxRows) {
        Object.keys(newExcelData.data).forEach((key) => {
          newExcelData.data[key].length = sliderValue
        })
      }
      generateAndDownloadNewExcelFile(newExcelData)
    } else if (actionType === 'map') {
      if (latitudeColumn && longitudeColumn && nameColumn && excelData?.data) {
        const latitudeKey = extractColumnKey(latitudeColumn)
        const longitudeKey = extractColumnKey(longitudeColumn)
        const nameKey = extractColumnKey(nameColumn)

        if (!latitudeKey || !longitudeKey || !nameKey) {
          message.error('Invalid column format. Please re-select columns.', 5)
          setError(true)
          return
        }

        const latitudes = excelData.data[latitudeKey]
        const longitudes = excelData.data[longitudeKey]

        if (!latitudes || !longitudes) {
          message.error('Selected columns do not contain valid data.', 5)
          setError(true)
          return
        }

        const validationMessage = validateLatLngData(latitudes, longitudes)
        if (validationMessage) {
          message.error(validationMessage, 5)
          return
        }

        const mapData = excelData.data[latitudeKey].map((_, idx) => ({
          id: idx,
          lat: excelData.data[latitudeKey][idx],
          lng: excelData.data[longitudeKey][idx],
          name: excelData.data[nameKey][idx],
          color: 'black',
        }))
        setMapPoints(mapData)
        setCurrentMapFile(excelData)
      } else {
        message.error('Please select all required columns.', 5)
        setError(true)
        return
      }
    }
    onCancel()
  }

  const validateLatLngData = (latitudes, longitudes) => {
    const latPattern = /^-?([1-8]?[0-9](\.\d+)?|90(\.0+)?)$/
    const lngPattern = /^-?((1[0-7][0-9]|[1-9]?[0-9])(\.\d+)?|180(\.0+)?)$/

    for (const lat of latitudes) {
      if (lat === null || lat === undefined || !latPattern.test(lat.toString())) {
        return `Invalid latitude value: ${lat}`
      }
    }

    for (const lng of longitudes) {
      if (lng === null || lng === undefined || !lngPattern.test(lng.toString())) {
        return `Invalid longitude value: ${lng}`
      }
    }

    return ''
  }

  useEffect(() => {
    if (excelData && selectedColumns.length === excelData.columns.length) {
      setSelectAll(true)
    } else if (selectedColumns.length === 0) {
      setSelectAll(false)
    }
  }, [selectedColumns, excelData?.columns])

  useEffect(() => {
    if (!visible) {
      setExcelData(null)
      setActionType(null)
      setError(false)
      setLatitudeColumn(null)
      setLongitudeColumn(null)
      setNameColumn(null)
      setSelectedColumns([])
      setSortColumn(null)
      setSortOrder('ascend')
      setCleanDataOptions({
        trimWhitespace: false,
        toUpperCase: false,
      })
    }
  }, [visible])

  return (
    <Modal
      open={visible}
      title="Excel Data Options"
      onCancel={onCancel}
      className={styles.excelColumnSelectorModal}
      footer={[
        <Button key="cancel" onClick={onCancel} className={styles.marginBottom20}>
          Cancel
        </Button>,
        <Button key="confirm" type="primary" onClick={handleConfirm} disabled={!actionType} className={styles.marginBottom20}>
          Confirm
        </Button>,
      ]}
    >
      <Spin spinning={isLoading} tip="Loading Excel data...">
        <Radio.Group onChange={(e) => setActionType(e.target.value)} value={actionType} className={styles.margins}>
          <Radio value="format">Data Cleaning</Radio>
          <Radio value="map">Display on Map</Radio>
        </Radio.Group>
        {excelData && actionType === 'format' && (
          <>
            <div className={styles.marginBottom20}>
              <h3 className={styles.excelColumnSelectorModalH3}>Select Columns to Keep:</h3>
              <Input
                type="text"
                placeholder="Search columns..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value.toLowerCase())}
                className={styles.inputSearch}
              />
              <div className={styles.selectAllContainer}>
                <Button
                  type={selectAll ? 'primary' : 'default'}
                  onClick={toggleSelectAll}
                >
                  {selectAll ? 'Deselect All' : 'Select All'}
                </Button>
              </div>
              <div className={styles.columnContainer}>
                {excelData.columns
                    .filter((column) => column.toLowerCase().includes(searchQuery))
                    .map((column, index) => (
                      <div key={column} className={styles.checkboxLabel}>
                        <span className={styles.columnPrefix}>
                          {index < 26 ? String.fromCharCode(65 + index) : (
                                              String.fromCharCode(64 + Math.floor(index / 26)) +
                                              String.fromCharCode(65 + (index % 26))
                                          )}
                        </span>
                        <Checkbox
                          onChange={() => handleCheckboxChange(column)}
                          checked={selectedColumns.includes(column)}
                        >
                          <span className="column-name">{column.replace(/\s+\([A-Z]\)$/, '')}</span>
                        </Checkbox>
                      </div>
                    ))}
              </div>
            </div>
            <div className={styles.marginBottom20}>
              <h3 className={styles.excelColumnSelectorModalH3}>Data Cleaning Options:</h3>
              <div>
                <Switch
                  checkedChildren="Trim"
                  unCheckedChildren="No Trim"
                  onChange={(checked) => handleDataCleaningSwitch(checked, 'trimWhitespace')}
                />
                <span className={styles.dataCleaningSwitch}>Trim Whitespace</span>
              </div>
              <div>
                <Switch
                  checkedChildren="Upper"
                  unCheckedChildren="No Upper"
                  onChange={(checked) => handleDataCleaningSwitch(checked, 'toUpperCase')}
                />
                <span className={styles.dataCleaningSwitch}>Convert Text to Uppercase</span>
              </div>
            </div>
            <div className={styles.marginBottom20}>
              <h3 className={styles.excelColumnSelectorModalH3}>Sorting Options:</h3>
              <Switch
                checkedChildren="Ascending"
                unCheckedChildren="Descending"
                onChange={(checked) => setSortOrder(checked ? 'ascend' : 'descend')}
              />
              <Select
                placeholder="Select Column to Sort"
                onChange={(value) => setSortColumn(value)}
                className={styles.sortSelectContainer}
              >
                {selectedColumns.map((column) => (
                  <Select.Option key={column} value={column}>
                    {column}
                  </Select.Option>
                ))}
              </Select>
            </div>
            <div className={styles.marginBottom20}>
              <h3 className={styles.excelColumnSelectorModalH3}>Number of Rows to Keep:</h3>
              <Slider
                min={1}
                max={maxRows}
                value={sliderValue}
                onChange={setSliderValue}
                marks={{
                  1: '1',
                  [maxRows]: maxRows,
                }}
              />
            </div>
          </>
        )}

        {excelData && actionType === 'map' && (
          <>
            <div className={styles.selectGroup}>
              {['Latitude', 'Longitude', 'Marker Name'].map((placeholder, index) => (
                <Select
                  key={placeholder}
                  className={`${styles.selectColumn} ${error && styles.errorSelect}`}
                  placeholder={`Select ${placeholder} Column`}
                  onChange={(value) => {
                    if (index === 0) setLatitudeColumn(value)
                    if (index === 1) setLongitudeColumn(value)
                    if (index === 2) setNameColumn(value)
                  }}
                >
                  {excelData.columns.map((column) => (
                    <Select.Option key={column} value={column}>
                      {column}
                    </Select.Option>
                  ))}
                </Select>
              ))}
            </div>
            <Alert
              className={styles.alertWarning}
              message="Note"
              description={
                <>
                  Ensure your data is geocoded (has coordinates).
                  <br />
                  Contact <a href="mailto:alonsdale@bernoullitechnologies.net">alonsdale@bernoullitechnologies.net</a> if you need this.
                </>
              }
              type="info"
              showIcon
            />
            {Object.keys(excelData.data).some((key) => excelData.data[key].length > 10000) && (
              <Alert
                className={styles.alertWarning}
                message="Warning"
                description="Large datasets may result in slow performance."
                type="warning"
                showIcon
              />
            )}
          </>
        )}
      </Spin>
    </Modal>
  )
}

export default ExcelColumnSelector
